package mx.com.mesaregia.seguridad.api.controller;
import lombok.RequiredArgsConstructor; import mx.com.mesaregia.seguridad.api.response.*; import mx.com.mesaregia.seguridad.application.service.AuditoriaService; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime;
@RestController @RequestMapping("/api/v1/auditoria") @RequiredArgsConstructor public class AuditoriaController {private final AuditoriaService service;@GetMapping @PreAuthorize("hasAuthority('auditoria.consultar')") public PageResponse<AuditoriaResponse> buscar(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)LocalDateTime desde,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)LocalDateTime hasta,@RequestParam(required=false)Long idUsuario,@RequestParam(required=false)String modulo,@RequestParam(required=false)String accion,@RequestParam(required=false)String correlacion,@PageableDefault(size=50)Pageable p){return service.buscar(desde,hasta,idUsuario,modulo,accion,correlacion,p);}}
